#!/usr/bin/env bash
# Re-runnable vendor pipeline for the NetSurf constellation.
#
#   ./update.sh [--src DIR]
#
# Rebuilds the committed vendor trees from upstream at the revisions pinned
# in UPSTREAM.json:  fetch pristine → generate (gperf/perl/gen_parser) →
# apply patches/ → prune to the vendored subset → relativize includes →
# install into this directory → drift-gate.  Running it against the pinned
# revisions must reproduce the committed trees byte-identically; to take a
# new upstream drop, bump UPSTREAM.json and re-run (then fix patch fuzz /
# new relativizations and re-verify with smoke.mjs).
#
#   --src DIR   use existing clones in DIR/<component> instead of cloning
#               (each must contain the pinned revision as a commit)
#
# Host tools needed: git, perl, gperf, cc (for libcss's gen_parser), node.
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
SRC_DIR=""
if [ "${1:-}" = "--src" ]; then SRC_DIR="$2"; shift 2; fi

COMPONENTS=(netsurf libwapcaplet libparserutils libhubbub libdom libcss libnsgif libnsbmp libnsutils libnsfb)

pin() { # component -> rev
  node -e "console.log(require('$HERE/UPSTREAM.json').components['$1'].rev)"
}
url() {
  node -e "console.log(require('$HERE/UPSTREAM.json').components['$1'].url)"
}

STAGE="$(mktemp -d /tmp/netsurf-vendor.XXXXXX)"
echo "staging in $STAGE"

# ---- 1. pristine trees at the pinned revisions ----
for c in "${COMPONENTS[@]}"; do
  rev="$(pin "$c")"
  mkdir -p "$STAGE/$c"
  if [ -n "$SRC_DIR" ]; then
    git -C "$SRC_DIR/$c" archive "$rev" | tar -x -C "$STAGE/$c"
  else
    tmp="$STAGE/.clone-$c"
    git clone --quiet "$(url "$c")" "$tmp"
    git -C "$tmp" archive "$rev" | tar -x -C "$STAGE/$c"
    rm -rf "$tmp"
  fi
  echo "  $c @ $rev"
done

# ---- 2. generated sources (committed; upstream gitignores them) ----
# Perl hash-iteration order leaks into the generated tables; pin the seed
# so regeneration at an unchanged pin is byte-identical to the commit.
export PERL_HASH_SEED=0 PERL_PERTURB_KEYS=0
echo "generating…"
( cd "$STAGE/libparserutils" && perl build/make-aliases.pl )          # src/charset/aliases.inc
( cd "$STAGE/libhubbub" && perl build/make-entities.pl )              # src/tokeniser/entities.inc
( cd "$STAGE/libhubbub/src/treebuilder" &&
  gperf --output-file=autogenerated-element-type.c.tmp element-type.gperf &&
  sed -e 's/^\(const struct element_type_map\)/static \1/' \
      autogenerated-element-type.c.tmp > autogenerated-element-type.c &&
  rm autogenerated-element-type.c.tmp )
( cd "$STAGE/libcss" &&
  cc -O2 -o "$STAGE/gen_parser" src/parse/properties/css_property_parser_gen.c &&
  cd src/parse/properties &&
  perl -ne 'print "$1\n" if /^([^#][^:]+):/' properties.gen | while read -r prop; do
    "$STAGE/gen_parser" -o "autogenerated_${prop}.c" "$(grep "^${prop}:" properties.gen)"
  done )
( cd "$STAGE/netsurf" &&
  perl tools/split-messages.pl -l en -p any -f messages resources/FatMessages \
    > resources/Messages.en )

# ---- 3. curated patches (content changes only; see README.md table) ----
echo "patching…"
for c in netsurf libparserutils libhubbub libcss libdom libnsfb; do
  [ -f "$HERE/patches/$c.diff" ] || continue
  ( cd "$STAGE/$c" && patch -p1 --no-backup-if-mismatch -s < "$HERE/patches/$c.diff" )
done

# ---- 4. prune to the vendored subset ----
echo "pruning…"
( cd "$STAGE/netsurf"
  rm -rf docs test Docs citools netsurf.workspace
  for f in frontends/*; do
    case "$f" in frontends/monkey) ;; *) rm -rf "$f" ;; esac
  done
  rm -rf frontends/monkey/res       # symlink farm for upstream's make; unused here
  rm -rf resources/ca-bundle resources/de resources/fr resources/it \
         resources/ja resources/nl resources/zh_CN
  # xxd.c is kept for regen-js-bindings.sh's .inc step (built with cc there,
  # the libcss gen_parser precedent) — nothing in THIS script needs it.
  find tools -type f ! -name 'split-messages.pl' ! -name 'xxd.c' -delete
  find tools -type d -empty -delete )
for c in libwapcaplet libparserutils libhubbub libcss libnsgif libnsbmp libnsutils libnsfb; do
  ( cd "$STAGE/$c" && rm -rf test tests docs examples perf build )
done
( cd "$STAGE/libdom" && rm -rf test tests docs examples build bindings/xml )
rm -f "$STAGE"/libnsfb/src/surface/{x,vnc,wld,sdl,able}.c
find "$STAGE" \( -name Makefile -o -name 'Makefile.*' -o -name '*.pc.in' -o -name '.gitignore' \) -delete

# ---- 5. include relativization (mechanical; see relativize.mjs) ----
node "$HERE/relativize.mjs" "$STAGE"

# ---- 6. install (preserving the in-component lib.jsons) ----
echo "installing…"
for c in "${COMPONENTS[@]}"; do
  if [ -f "$HERE/$c/lib.json" ]; then cp "$HERE/$c/lib.json" "$STAGE/$c/lib.json"; fi
  rm -rf "${HERE:?}/$c"
  cp -R "$STAGE/$c" "$HERE/$c"
done
rm -rf "$STAGE"

# ---- 7. drift gate ----
node "$HERE/relativize.mjs" "$HERE" --check
echo "done. Now run: node vendor/netsurf/smoke.mjs"
